import C1Kit
import Foundation

/// `docs/reference/commands.md`: the command table, with each example's result recorded against FakeCaptureOne.
enum Reference {
    static let path = "docs/reference/commands.md"

    static func markdown() throws -> String {
        let results = try record()
        var lines = [
            "# c1 command reference",
            "",
            "Generated by `scripts/v2-generate.sh` from the command table in `Sources/C1Kit`; do not edit. Example results are recorded against the fake Capture One in `Tests/C1KitTests`, so their values are illustrative. `c1 <command> --help` prints the same facts.",
            "",
        ]
        lines += Command.general.flatMap { [$0, ""] }
        lines += ["| Command | Changes variants | Summary |", "|---|---|---|"]
        lines += Command.allCases.map { "| [`\($0.rawValue)`](#\($0.rawValue)) | \($0.readOnly ? "no" : "yes") | \(cell($0.summary)) |" }
        lines += ["", "## Failure codes", "", "A failed call prints `{\"error\": {code, message, hint?, outcome?}}` and exits 1; with `outcome: unknown` it may have run in Capture One, and exits 0.", "",
                  "| Code | Meaning |", "|---|---|"]
        lines += C1Failure.Code.allCases.map { "| `\($0.rawValue)` | \(cell($0.meaning)) |" }
        for command in Command.allCases {
            lines += ["", "## \(command.rawValue)", "", command.summary, ""]
            lines += command.details.flatMap { [$0, ""] }
            lines += ["### Arguments", ""]
            if command.arguments.isEmpty {
                lines += ["None; pass `{}` or nothing.", ""]
            } else {
                lines += ["| Name | Type | Required | Range | Values | Description |", "|---|---|---|---|---|---|"]
                lines += rows(command.arguments, prefix: "") + [""]
            }
            if command == .set {
                lines += ["### Fields", "", "Named as `get` reports them; ranges were measured on Capture One 16.8.5.30.", "", "| Field | Type and range |", "|---|---|"]
                lines += Command.setFields().map { "| `\($0.path)` | \(cell($0.type)) |" } + [""]
            }
            if command == .action {
                lines += ["### Actions", "", "| Action | Arguments | Summary |", "|---|---|---|"]
                lines += Action.allCases.map { "| `\($0.rawValue)` | \($0.arguments.map { "`\($0)`" }.joined(separator: ", ")) | \(cell($0.summary)) |" } + [""]
            }
            lines += ["### Example", "", "```sh", "c1 \(command.rawValue) '\(command.example)'", "```", "", "```json", results[command]!, "```", ""]
            lines += ["### Errors", "", "Failures: \(command.failures.map { "`\($0.rawValue)`" }.joined(separator: ", "))."]
            if !command.variantErrors.isEmpty {
                lines += ["", "Per-variant errors, beside other variants' results: \(command.variantErrors.map { "`\($0)`" }.joined(separator: ", "))."]
            }
        }
        return lines.joined(separator: "\n") + "\n"
    }

    static func cell(_ text: String) -> String { text.replacingOccurrences(of: "|", with: "\\|") }

    static func rows(_ arguments: [Argument], prefix: String) -> [String] {
        arguments.flatMap { argument -> [String] in
            let row = "| `\(prefix)\(argument.name)` | \(cell(argument.type)) | \(argument.required ? "yes" : "no") | \(argument.range ?? "") | \(argument.values?.map { "`\($0)`" }.joined(separator: ", ") ?? "") | \(cell(argument.description)) |"
            switch argument.kind {
            case .object(let keys): return [row] + rows(keys, prefix: "\(prefix)\(argument.name).")
            case .list(.object(let keys), _): return [row] + rows(keys, prefix: "\(prefix)\(argument.name)[].")
            default: return [row]
            }
        }
    }

    /// Runs every example in table order on one fake document, so revert finds set's snapshot.
    static func record() throws -> [Command: String] {
        let now = Date(timeIntervalSince1970: 1_800_000_000)
        let originals = scratchDirectory("photos")
        FakeCaptureOne.writeJPEG(FakeCaptureOne.gradient(area: [1500, 1000, 3000, 2000], canvas: [3000, 2000], longEdge: 3000),
                                 to: originals.appendingPathComponent("a.jpg"))
        let sql = """
            UPDATE ZDOCUMENTCONTENT SET ZLASTBACKUPDATE=\(now.timeIntervalSince1970 - 3600);
            UPDATE ZPATHLOCATION SET ZRELATIVEPATH='\(originals.path.dropFirst())' WHERE Z_PK=100;
            UPDATE ZIMAGE SET ZIMAGEFILENAME='a.jpg' WHERE Z_PK=1;
            """
        let database = Fixture.make("reference", extraSQL: sql)
        ViewingTests.writeCot(scratchURL("reference").appendingPathComponent("Cache/Thumbnails/00000001.cot"), width: 300, height: 200, comment: "3|0;0;0|0;200;300;0|0")
        let home = scratchDirectory("reference-home"), caches = scratchDirectory("reference-caches")
        let fake = FakeCaptureOne()
        fake.variants = [.collection(cid("10")): [id("1"): state("1"), id("2"): state("2")]]
        fake.selected = [id("1"), id("2")]
        let service = Service(captureOne: fake, queue: CaptureOneQueue(directory: scratchDirectory("reference-queue")),
                              home: home, caches: caches, openDatabase: { _ in try Database(path: database) },
                              defaults: { try Defaults.bundled() },
                              schema: { WriteSchema(terminology: .snapshot, bounds: try BoundsTable.bundled()) },
                              now: { now }, liveTerms: { .snapshot })
        let replacements = [(home.path, "~/.c1"), (caches.path, "~/Library/Caches/c1"), (originals.path, "/photos")]
        var results: [Command: String] = [:]
        for command in Command.allCases {
            let value: JSONValue
            do { value = try command.run(service, arguments: Data(command.example.utf8)) } catch let failure as C1Failure { value = failure.json }
            var text = value.droppingNulls().encoded(pretty: true)
            for (from, to) in replacements { text = text.replacingOccurrences(of: from, with: to) }
            // Layer tags and file names are random per call.
            text = text.replacingOccurrences(of: #"c1:[a-z2-9]{6}"#, with: "c1:k7mq2x", options: .regularExpression)
            text = text.replacingOccurrences(of: #"-[0-9a-f]{8}\.jpg"#, with: "-3f9c2a1e.jpg", options: .regularExpression)
            results[command] = text
        }
        return results
    }

    /// An imported variant with Capture One's defaults, already at exposure 0.7 and rated 3.
    static func state(_ id: String) -> VariantState {
        let defaults = try! Defaults.bundled().defaults
        var variant = defaults["variant"]!
        variant["id"] = .string(id); variant["name"] = .string(id == "1" ? "a" : "b"); variant["rating"] = .int(3)
        variant["crop"] = .array([.int(3000), .int(2000), .int(6000), .int(4000)])
        var adjustments = defaults["adjustments"]!
        adjustments["exposure"] = .double(0.7); adjustments["temperature"] = .double(5150); adjustments["tint"] = .double(2)
        return VariantState(id: VariantID(id)!, variant: variant, adjustments: adjustments, lensCorrection: defaults["lensCorrection"]!,
                            layers: [["kind": .string("background"), "name": .string("Background"), "opacity": .int(100), "enabled": .bool(true)]],
                            canvasSize: [6000, 4000], maximumCrop: [3000, 2000, 6000, 4000])
    }
}
